<script setup lang="ts">
import { ref, onUnmounted } from 'vue'; import Button from 'primevue/button'; import Textarea from 'primevue/textarea'; import Select from 'primevue/select'; import { useToast } from 'primevue/usetoast'; import { api, accessToken } from '../lib/api'; import { useQuery } from '../composables/useQuery'; import { date, type Data } from '../lib/types'; import QueryState from './QueryState.vue'; import StatusBadge from './StatusBadge.vue';
const props=defineProps<{driverId:string}>();const toast=useToast(),selected=ref<Data>(),decision=ref('APPROVED'),reason=ref(''),busy=ref(false),preview=ref('');
const names:Record<string,string>={IDENTITY:'Giấy tờ định danh',DRIVING_LICENSE:'Giấy phép lái xe',VEHICLE_REGISTRATION:'Đăng ký phương tiện',INSURANCE:'Bảo hiểm'};
const {data,loading,error,refresh}=useQuery(()=>api('/admin/drivers/'+props.driverId+'/documents'));
async function view(doc:Data){try{const response=await fetch((import.meta.env.VITE_API_BASE_URL??'')+'/api/v1/files/'+doc.fileId+'/content',{headers:{Authorization:'Bearer '+await accessToken()}});if(!response.ok)throw new Error('Không thể tải giấy tờ hoặc quyền xem đã hết hiệu lực.');if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(await response.blob());}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}}
async function review(){if(!selected.value)return;busy.value=true;try{await api('/admin/driver-documents/'+selected.value.id+'/review-decisions',{method:'POST',body:{expectedVersion:selected.value.version,decision:decision.value,reasonCode:reason.value}});selected.value=undefined;reason.value='';await refresh();toast.add({severity:'success',summary:'Đã lưu kết quả duyệt giấy tờ',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
onUnmounted(()=>{if(preview.value)URL.revokeObjectURL(preview.value);});
</script>
<template><div class="document-review"><h3>Giấy tờ đối tác</h3><QueryState :loading="loading" :error="error" @retry="refresh"/><p v-if="data&&!data.items.length" class="muted">Hồ sơ mẫu chưa đính kèm file. Hồ sơ mới cần nộp đầy đủ giấy tờ trước khi được duyệt.</p><div v-for="doc in data?.items??[]" :key="doc.id" class="document-row"><div><strong>{{names[doc.type]??doc.type}}</strong><small>Phiên bản {{doc.version}} · Hạn {{date(doc.expiresAt,false)}}</small></div><StatusBadge :status="doc.status"/><Button icon="pi pi-eye" text aria-label="Xem giấy tờ private" @click="view(doc)"/><Button label="Duyệt" text size="small" @click="selected=doc;reason=''"/></div><img v-if="preview" :src="preview" class="document-preview" alt="Giấy tờ private của đối tác đang xét duyệt"/><div v-if="selected" class="document-form"><label>Kết quả giấy tờ<Select v-model="decision" :options="[{label:'Chấp thuận',value:'APPROVED'},{label:'Cần bổ sung',value:'REJECTED'}]" option-label="label" option-value="value"/></label><label>Lý do / nhận xét<Textarea v-model="reason" rows="2"/></label><Button label="Lưu kết quả giấy tờ" :loading="busy" :disabled="reason.trim().length<3" @click="review"/></div></div></template>
<style scoped>.document-review{border-top:1px solid #edf1ef;margin:20px 0;padding-top:18px}.document-review h3{font-size:12px}.document-review>p{font-size:10px;line-height:1.9}.document-row{display:flex;align-items:center;gap:8px;padding:12px 0;border-top:1px solid #f0f3f1}.document-row>div{flex:1}.document-row strong{font-size:10px;display:block;font-weight:550}.document-row small{font-size:8px;color:#9daaa2;display:block;margin-top:6px}.document-preview{display:block;max-width:100%;max-height:380px;object-fit:contain;border:1px solid #e7ece8;border-radius:8px;margin:12px auto}.document-form{padding:15px;background:#f5f9f6;border:1px solid #e3eee6;border-radius:8px;margin-top:12px}</style>
